func TestNewGitStoreWithOptions_RejectsInvalidRefs(t *testing.T) {
	t.Parallel()

	repo := initGitStoreOptionsRepo(t)
	tests := []struct {
		name string
		opts GitStoreOptions
	}{
		{
			name: "empty committed ref",
			opts: GitStoreOptions{},
		},
		{
			name: "committed ref shorthand",
