}

func TestGitStore_WriteCommitted_CustomCommittedRef(t *testing.T) {
	t.Parallel()

	repo := initGitStoreOptionsRepo(t)
	store, err := NewGitStoreWithOptions(repo, GitStoreOptions{
		CommittedRef: plumbing.ReferenceName(paths.CheckpointsV11RefName),
	})
