		slog.String("session_id", opts.SessionID),
		slog.String("checkpoint_id", opts.CheckpointID.String()),
		slog.String("agent", string(opts.Agent)),
		slog.Int64("chunk_transcript_ms", chunkDuration.Milliseconds()),
