@@
 package checkpoint

 import (
+	"fmt"
+	"strings"
+
+	"github.com/entireio/cli/cmd/entire/cli/paths"
+
 	"github.com/go-git/go-git/v6"
+	"github.com/go-git/go-git/v6/plumbing"
 )
@@
 type GitStore struct {
-	repo        *git.Repository
-	blobFetcher BlobFetchFunc
+	repo          *git.Repository
+	blobFetcher  BlobFetchFunc
+	committedRef plumbing.ReferenceName
+	seedRef      plumbing.ReferenceName
 }

+// GitStoreOptions configures checkpoint refs for a GitStore.
+type GitStoreOptions struct {
+	CommittedRef plumbing.ReferenceName
+	SeedRef      plumbing.ReferenceName
+}
+
 // NewGitStore creates a new checkpoint store backed by the given git repository.
 func NewGitStore(repo *git.Repository) *GitStore {
-	return &GitStore{repo: repo}
+	return &GitStore{
+		repo:          repo,
+		committedRef: plumbing.ReferenceName(paths.MetadataBranchRefName),
+	}
+}
+
+// NewGitStoreWithOptions creates a checkpoint store with an explicit committed ref.
+func NewGitStoreWithOptions(repo *git.Repository, opts GitStoreOptions) (*GitStore, error) {
+	if err := validateFullReferenceName("committed ref", opts.CommittedRef); err != nil {
+		return nil, err
+	}
+	if opts.SeedRef != "" {
+		if err := validateFullReferenceName("seed ref", opts.SeedRef); err != nil {
+			return nil, err
+		}
+		if opts.SeedRef == opts.CommittedRef {
+			return nil, fmt.Errorf("seed ref %q must differ from committed ref", opts.SeedRef)
+		}
+	}
+
+	return &GitStore{
+		repo:          repo,
+		committedRef: opts.CommittedRef,
+		seedRef:      opts.SeedRef,
+	}, nil
+}
+
+// CommittedRef returns the full ref used for committed checkpoint metadata.
+func (s *GitStore) CommittedRef() plumbing.ReferenceName {
+	if s.committedRef == "" {
+		return plumbing.ReferenceName(paths.MetadataBranchRefName)
+	}
+	return s.committedRef
 }
@@
 func (s *GitStore) Repository() *git.Repository {
 	return s.repo
 }
+
+func (s *GitStore) usesDefaultCommittedRef() bool {
+	return s.CommittedRef() == plumbing.ReferenceName(paths.MetadataBranchRefName)
+}
+
+func (s *GitStore) setCommittedRef(hash plumbing.Hash) error {
+	ref := plumbing.NewHashReference(s.CommittedRef(), hash)
+	if err := s.repo.Storer.SetReference(ref); err != nil {
+		return fmt.Errorf("failed to set checkpoint reference %s: %w", s.CommittedRef(), err)
+	}
+	return nil
+}
+
+func validateFullReferenceName(label string, ref plumbing.ReferenceName) error {
+	if ref == "" {
+		return fmt.Errorf("%s is required", label)
+	}
+	if !strings.HasPrefix(string(ref), "refs/") {
+		return fmt.Errorf("%s %q must be a full refs/... name", label, ref)
+	}
+	return nil
+}
