package checkpoint

import (
	"context"
	"errors"
	"fmt"
	"log/slog"

	"github.com/entireio/cli/cmd/entire/cli/logging"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
)

type committedStore interface {
	WriteCommitted(ctx context.Context, opts WriteCommittedOptions) (plumbing.Hash, error)
	UpdateCommitted(ctx context.Context, opts UpdateCommittedOptions) (plumbing.Hash, error)
}

var (
	_ committedStore = (*GitStore)(nil)
	_ committedStore = (*MirroringCommittedStore)(nil)
)

// MirroringCommittedStore writes committed checkpoints to a primary store and
// best-effort mirrors one secondary ref to the same commit.
type MirroringCommittedStore struct {
	primary   committedStore
	repo      *git.Repository
	mirrorRef plumbing.ReferenceName
}

// NewMirroringCommittedStore creates a committed store that mirrors successful
// primary writes to mirrorRef.
func NewMirroringCommittedStore(repo *git.Repository, primary committedStore, mirrorRef plumbing.ReferenceName) (*MirroringCommittedStore, error) {
	if repo == nil {
		return nil, errors.New("git repository is required")
	}
	if primary == nil {
		return nil, errors.New("primary committed store is required")
	}
	if err := validateFullReferenceName("mirror ref", mirrorRef); err != nil {
		return nil, err
	}

	return &MirroringCommittedStore{
		primary:   primary,
		repo:      repo,
		mirrorRef: mirrorRef,
	}, nil
}

func (s *MirroringCommittedStore) WriteCommitted(ctx context.Context, opts WriteCommittedOptions) (plumbing.Hash, error) {
	commitHash, err := s.primary.WriteCommitted(ctx, opts)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("write committed checkpoint: %w", err)
	}
	s.mirror(ctx, commitHash)
	return commitHash, nil
}

func (s *MirroringCommittedStore) UpdateCommitted(ctx context.Context, opts UpdateCommittedOptions) (plumbing.Hash, error) {
	commitHash, err := s.primary.UpdateCommitted(ctx, opts)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("update committed checkpoint: %w", err)
	}
	s.mirror(ctx, commitHash)
	return commitHash, nil
}

func (s *MirroringCommittedStore) mirror(ctx context.Context, targetHash plumbing.Hash) {
	logCtx := logging.WithComponent(ctx, "checkpoint")

	if targetHash == plumbing.ZeroHash {
		logging.Warn(logCtx, "committed checkpoint mirror skipped: primary returned zero hash",
			slog.String("mirror_ref", string(s.mirrorRef)),
		)
		return
	}

	targetCommit, err := s.repo.CommitObject(targetHash)
	if err != nil {
		logging.Warn(logCtx, "committed checkpoint mirror skipped: target commit is unavailable",
			slog.String("mirror_ref", string(s.mirrorRef)),
			slog.String("target_hash", targetHash.String()),
			slog.String("error", err.Error()),
		)
		return
	}

	currentRef, err := s.repo.Reference(s.mirrorRef, true)
	if errors.Is(err, plumbing.ErrReferenceNotFound) {
		s.setMirrorRef(logCtx, targetHash)
		return
	}
	if err != nil {
		logging.Warn(logCtx, "committed checkpoint mirror skipped: mirror ref is unavailable",
			slog.String("mirror_ref", string(s.mirrorRef)),
			slog.String("target_hash", targetHash.String()),
			slog.String("error", err.Error()),
		)
		return
	}
	if currentRef.Hash() == targetHash {
		return
	}

	currentCommit, err := s.repo.CommitObject(currentRef.Hash())
	if err != nil {
		logging.Warn(logCtx, "committed checkpoint mirror skipped: mirror commit is unavailable",
			slog.String("mirror_ref", string(s.mirrorRef)),
			slog.String("mirror_hash", currentRef.Hash().String()),
			slog.String("target_hash", targetHash.String()),
			slog.String("error", err.Error()),
		)
		return
	}

	ancestor, err := currentCommit.IsAncestor(targetCommit)
	if err != nil {
		logging.Warn(logCtx, "committed checkpoint mirror skipped: ancestry check failed",
			slog.String("mirror_ref", string(s.mirrorRef)),
			slog.String("mirror_hash", currentRef.Hash().String()),
			slog.String("target_hash", targetHash.String()),
			slog.String("error", err.Error()),
		)
		return
	}
	if !ancestor {
		logging.Warn(logCtx, "committed checkpoint mirror skipped: mirror ref has diverged",
			slog.String("mirror_ref", string(s.mirrorRef)),
			slog.String("mirror_hash", currentRef.Hash().String()),
			slog.String("target_hash", targetHash.String()),
		)
		return
	}

	s.setMirrorRef(logCtx, targetHash)
}

func (s *MirroringCommittedStore) setMirrorRef(ctx context.Context, targetHash plumbing.Hash) {
	ref := plumbing.NewHashReference(s.mirrorRef, targetHash)
	if err := s.repo.Storer.SetReference(ref); err != nil {
		if retryErr := s.repo.Storer.SetReference(ref); retryErr != nil {
			logging.Warn(ctx, "committed checkpoint mirror skipped: failed to update mirror ref",
				slog.String("mirror_ref", string(s.mirrorRef)),
				slog.String("target_hash", targetHash.String()),
				slog.String("error", fmt.Sprintf("%v; retry: %v", err, retryErr)),
			)
		}
	}
}

