func (s *EntireSettings) EffectiveCheckpointsVersion(ctx context.Context) CheckpointsVersion {
	if s == nil || s.StrategyOptions == nil {
		return CheckpointsVersion1
	}

	raw, ok := s.StrategyOptions[checkpointsVersionOptionKey]
	if !ok {
		return CheckpointsVersion1
	}

	version, ok := raw.(string)
	if !ok {
		logInvalidCheckpointsVersion(ctx, raw)
		return CheckpointsVersion1
